"""Generate docs/prompts/prompt-catalog.md from the call specs (brief 7.2).

Specs not written yet are listed as "planned". Deterministic output.
"""

from __future__ import annotations

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
OUT = ROOT / "docs" / "prompts" / "prompt-catalog.md"


def main() -> int:
    from mde_contracts.registry import CALL_IO
    from mde_prompts.registry import SpecNotFound, load_spec

    lines = [
        "# Prompt catalog",
        "",
        "Generated by `scripts/gen_prompt_catalog.py` from the call specs. Do not edit by hand.",
        "",
        "| Call | Version | Route | Effort | Max out | Tools | Untrusted | Fallback |",
        "| --- | --- | --- | --- | --- | --- | --- | --- |",
    ]
    details: list[str] = []
    for call_id in CALL_IO:
        try:
            spec = load_spec(call_id)
        except SpecNotFound:
            lines.append(f"| {call_id} | planned | | | | | | |")
            continue
        tools = ",".join(t.kind for t in spec.tools) or "-"
        untrusted = ",".join(spec.untrusted_inputs) or "-"
        lines.append(
            f"| {spec.id} | {spec.version} | {spec.route} | {spec.reasoning_effort} | "
            f"{spec.max_output_tokens} | {tools} | {untrusted} | {spec.fallback or '-'} |"
        )
        sys_t = (spec.template_root / spec.system_template).read_text(encoding="utf-8")
        out_name = spec.output_model.__name__ if spec.output_model else "free text"
        details += [
            f"## {spec.id} (v{spec.version})",
            "",
            f"Input: `{spec.input_model.__name__}`; output: `{out_name}`; mock: `{spec.mock_handler}`.",
            "",
            "System prompt:",
            "",
            "```jinja",
            sys_t.rstrip(),
            "```",
            "",
        ]
    OUT.parent.mkdir(parents=True, exist_ok=True)
    OUT.write_text("\n".join([*lines, "", *details]) + "\n", encoding="utf-8", newline="\n")
    print(f"wrote {OUT.relative_to(ROOT)}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
